const subsidies = ($input.first().json.records || []).filter(s => s.fields.status === 'Active');
const children = ($input.all()[1]?.json?.records || []);
const today = new Date();
const alerts = [];

for (const sub of subsidies) {
  const f = sub.fields;
  const reauth = new Date(f.reauthorization_date);
  const daysUntil = Math.ceil((reauth - today) / (1000 * 60 * 60 * 24));

  if (daysUntil <= 14 && daysUntil >= 0) {
    const child = children.find(c => String(c.id) === String(f.child));
    const childName = child ? child.fields.first_name + ' ' + child.fields.last_name : `Child #${f.child}`;
    const urgency = daysUntil <= 7 ? '🚨 URGENT' : '⚠️';
    alerts.push({
      child_name: childName,
      program: f.program_name,
      amount: f.monthly_amount,
      reauth_date: f.reauthorization_date,
      days_until: daysUntil,
      case_worker: f.case_worker,
      case_worker_phone: f.case_worker_phone,
      urgency: urgency,
      notes: f.notes || ''
    });
  }
}

if (alerts.length === 0) {
  alerts.push({summary: '✅ No subsidy deadlines within 14 days.', urgent_count: 0});
}

const totalAmount = subsidies.reduce((sum, s) => sum + (s.fields.monthly_amount || 0), 0);
const firstItem = alerts[0];
firstItem.total_active = subsidies.length;
firstItem.total_monthly = totalAmount;

return alerts.map(a => ({json: a}));

const data = $input.first().json;

if (data.summary) {
  return [{json: {message: data.summary, notify: false}}];
}

let message = `💰 *Subsidy Reauthorization Alert*\n\n`;
message += `Active subsidies: ${data.total_active}\n`;
message += `Monthly total: $${data.total_monthly?.toLocaleString()}\n\n`;
message += `*Deadline:* ${data.child_name}\n`;
message += `${data.urgency} ${data.program}: $${data.amount}/mo\n`;
message += `Reauthorization: ${data.reauth_date} (${data.days_until} days)\n`;
message += `Case Worker: ${data.case_worker} — ${data.case_worker_phone}\n`;
if (data.notes) message += `Note: ${data.notes}\n`;
message += `\nAction: Contact case worker to schedule reauthorization.`;

return [{json: {message: message, notify: true}}];
